// ── i18n behavioral tests ──────────────────────────────────────────────────────
// Verifies the IDE-UI translation layer (form/COBOL content stays English by the
// project's CRITICAL constraint, so it is intentionally NOT translated).
#[cfg(test)]
mod i18n_tests {
    use super::*;

    /// A representative spread of common UI strings (across menus, panels, labels).
    fn sample(t: &Tr) -> Vec<&'static str> {
        vec![
            t.menu_file,
            t.menu_run,
            t.menu_run_btn,
            t.close_save,
            t.close_cancel,
            t.delete_confirm_title,
            t.delete_confirm_message,
            t.delete_confirm_cancel,
            t.delete_confirm_ok,
            t.clipboard_cut,
            t.clipboard_copy,
            t.clipboard_paste,
            t.clipboard_duplicate,
            t.uc_create,
            t.uc_name_prompt,
            t.uc_name_invalid,
            t.uc_name_duplicate,
            t.uc_circular_ref,
            t.uc_delete,
            t.uc_delete_confirm,
            t.uc_section_title,
            t.uc_child_controls,
            t.toolbox_collapse,
            t.toolbox_expand,
            t.props_hide,
            t.props_show,
            t.panel_output,
            t.panel_clear,
            t.panel_debugger,
            t.panel_project,
            t.panel_sources,
            t.panel_forms,
            t.panel_assets,
            t.lbl_back_color,
            t.lbl_fore_color,
            t.lbl_tab_order,
            t.data_binding_target_ready,
            t.data_binding_array_member,
            t.data_binding_choose_source,
            t.data_binding_source_indexed,
            t.data_binding_source_sql,
            t.data_binding_source_cobol_table,
            t.data_binding_source_rest,
            t.data_binding_source_agent,
            t.data_binding_guardian_blocked,
            t.data_binding_guardian_warning,
            t.data_binding_severity_blocker,
            t.data_binding_severity_warning,
            t.data_binding_severity_info,
            t.data_binding_repair_remap,
            t.data_binding_repair_remove_mapping,
            t.data_binding_repair_mark_read_only,
            t.data_binding_repair_refresh_saved,
            t.data_binding_repair_refresh_source,
            t.data_binding_repair_reselect_target,
            t.dg_section,
            t.dg_columns_multiline,
            t.dg_allow_column_resize,
            t.dg_allow_column_reorder,
            t.dg_show_filters,
            t.dg_selectable_text,
            t.dg_selection_mode,
            t.dg_frozen_columns,
            t.dg_frozen_rows,
            t.dg_grid_line_style,
            t.dg_csv_section,
            t.dg_enable_csv_export,
            t.dg_show_csv_button,
            t.dg_csv_mode,
            t.dg_csv_delimiter,
            t.dg_csv_hint,
            t.agent_actions_header,
            t.action_receiving_request,
            t.action_retrieving_context,
            t.action_planning,
            t.action_drafting,
            t.action_running_tool,
            t.action_reviewing,
            t.action_applying_corrections,
            t.action_finishing,
            t.action_blocked,
            t.action_failed,
            t.rag_token_savings,
            t.kb_indexing,
        ]
    }

    #[test]
    fn all_languages_with_unique_native_names() {
        assert_eq!(
            Language::ALL.len(),
            6,
            "expected 6 languages (EN/ES/PT/JA/ZH/FR)"
        );
        let names: Vec<&str> = Language::ALL.iter().map(|l| l.native_name()).collect();
        for n in &names {
            assert!(!n.trim().is_empty(), "empty native name");
        }
        let mut uniq = names.clone();
        uniq.sort();
        uniq.dedup();
        assert_eq!(uniq.len(), names.len(), "native names are not unique");
    }

    /// Spec 048 R2/AC1 — the surface is the **Model Providers Manager** in
    /// every language, and the old name is gone from all six tables.
    ///
    /// A provider is now configured once and every model it offers becomes
    /// available, so "Models Manager" no longer describes what the window does.
    /// Renaming five of six languages and leaving one behind is exactly the
    /// kind of miss a completeness sweep exists to catch.
    #[test]
    fn no_surface_still_says_models_manager() {
        let expected: &[(Language, &str)] = &[
            (Language::English, "Model Providers Manager"),
            (Language::Spanish, "Gestor de proveedores de modelos"),
            (Language::Portuguese, "Gerenciador de provedores de modelos"),
            (Language::Japanese, "モデル プロバイダー マネージャー"),
            (Language::Chinese, "模型提供商管理器"),
            (Language::French, "Gestionnaire de fournisseurs de modèles"),
        ];
        assert_eq!(expected.len(), Language::ALL.len());
        for (lang, title) in expected {
            assert_eq!(
                lang.tr().providers_title,
                *title,
                "{lang:?} must name the provider manager"
            );
        }
        // The retired English wording must not survive anywhere, in any
        // language's table, under any key.
        for &lang in Language::ALL {
            let t = lang.tr();
            for field in sample(&t) {
                assert!(
                    !field.contains("Models Manager"),
                    "{lang:?} still says \"Models Manager\": {field}"
                );
            }
        }
        println!(
            "provider manager named in {} languages; \"Models Manager\" absent from all",
            Language::ALL.len()
        );
    }

    #[test]
    fn no_empty_ui_translations() {
        for &lang in Language::ALL {
            let t = lang.tr();
            for (i, s) in sample(&t).iter().enumerate() {
                assert!(
                    !s.trim().is_empty(),
                    "{lang:?}: sample UI field #{i} is empty"
                );
            }
        }
    }

    #[test]
    fn non_english_is_actually_translated() {
        let en = sample(&Language::English.tr());
        for &lang in Language::ALL {
            if lang == Language::English {
                continue;
            }
            let other = sample(&lang.tr());
            let diff = en.iter().zip(other.iter()).filter(|(a, b)| a != b).count();
            assert!(
                diff * 100 / en.len() >= 60,
                "{lang:?}: only {diff}/{} sampled UI strings differ from English — looks untranslated",
                en.len()
            );
        }
    }
}
